  style?: React.CSSProperties;
  /** Replace the marking rendering entirely (e.g. per-object-type tokens). */
  renderMarking?: () => React.ReactNode;
  /** Extra editable control rendered inside the place (e.g. object-type select). */
  renderControls?: () => React.ReactNode;
  /** Consumer attribute: the object type this place belongs to (OCPN). Stored on the
   *  node so the editor is the single source of truth; serialized back out. */
  objectType?: string;
};

export interface PlaceInfo {
  id: string;
  /** Token count from the net's initial marking (before any override). */
  tokens: number;
  /** Token count from the net's final marking (before any override). */
  finalTokens: number;
}

/** What a place resolver returns; adds marking controls. */
export interface PlacePresentation extends ElementInteractions {
  style?: CSSProperties;
  className?: string;
  label?: string;
  /** Token count to draw (overrides the initial marking). */
  tokens?: number;
  /** Color of the default token dots. */
  tokenColor?: string;
  /** Explicit per-token marks (dots/squares, colored/faded); rendered in both the
   *  DOM node and the SVG export. Takes precedence over `tokens`. */
  tokenMarks?: TokenMark[];
  /** Object type this place belongs to (OCPN). Used purely as a layout grouping so each type
   *  forms a consistent lane; does not affect rendering. */
  objectType?: string;
  /** Render the marking yourself (e.g. per-object-type tokens). */
  renderMarking?: () => ReactNode;
  /** Extra editable control rendered inside the place (e.g. an object-type select). */
  renderControls?: () => ReactNode;
}

export interface ProcessTree {
  root: PTNode;
}

/** Positions nodes by centre, matching the editor's `nodeOrigin=[0.5,0.5]`. Edges stay unrouted:
 *  a tree edge is a straight parent->child line the edge geometry clips to the node borders. */
export type ProcessTreeLayoutFn = (
  nodes: ProcessTreeNode[],
  edges: Edge[],
) => Promise<{ nodes: ProcessTreeNode[]; edges: Edge[] }>;

export type ProcessTreeNode =
  | (Node<OperatorData> & { type: "operator" })
  | (Node<LeafData> & { type: "leaf" });

export interface ProcessTreeViewerProps
  extends ViewerProps<ProcessTree>,
    Pick<TreeEditorProps, "editable" | "onChange" | "renderSvg" | "nodeOverlay" | "exportKey"> {}

export interface ProcessTreeWorkbenchProps extends ViewerProps<ProcessTree> {
  /** Mode shown on mount. Defaults to "view". */
  initialMode?: ProcessTreeMode;
  /** Fired whenever the current (possibly edited) tree changes. */
  onTreeChange?: (tree: ProcessTree) => void;
  /** Host-supplied buttons; receive the current tree. */
  toolbar?: (tree: ProcessTree) => ReactNode;
  renderSvg?: StyledGraphRenderer;
}

export type PTNode =
  | { type: "Operator"; operator_type: OperatorType; children: PTNode[] }
  | { type: "Leaf"; activity_label: LeafLabel };

export interface RankedBarListProps {
  items: FreqItem[] | Record<string, number>;
  /** Scope passed to the shared colorOf resolver (e.g. "activity", "objectType"). */
  scope?: string;
  /** Override the color resolver; defaults to the shared ViewerConfig colorOf. */
  colorOf?: ColorResolver;
  /** Show at most this many rows (highest counts first). */
  max?: number;
  /** Format the value shown on the right (default: localized integer). */
  valueFormat?: (n: number) => string;
  onItemClick?: (key: string) => void;
  /** Key of the currently-selected row, highlighted with an accent background + ring. */
  selectedKey?: string;
  emptyText?: string;
}

export interface ResolvedMove {
  kind: MoveKind;
  /** Human-readable label: activity name for sync/log moves, transition label for model moves. */
  label: string;
  /** Transition has no label (invisible/tau). */
  hidden: boolean;
}

export interface SelectionActionsProps {
  /** Full set of selectable keys (for All / Invert). */
  allKeys: string[];
  value: Set<string>;
  onChange: (next: Set<string>) => void;
  size?: "1" | "2";
}

/** A replay trace plus token-replay bookkeeping (produced/consumed/missing/remaining). */
export interface SimTrace {
  steps: SimTraceStep[];
  /** Whether the marking was accepting (final marking reached) when the trace ended. */
  accepting: boolean;
  /** Tokens produced: initial marking plus every fired transition's output weights. */
  produced: number;
  /** Tokens consumed: every fired transition's input weights plus the final marking. */
  consumed: number;
  /** Tokens that had to be created to fire (input shortfall on a forced fire, plus any
   *  final-marking shortfall at trace end). */
  missing: number;
  /** Tokens left in the marking after consuming the final marking, at trace end. */
  remaining: number;
}

/** One fired step of a simulation trace. */
export interface SimTraceStep {
  transitionId: string;
  /** Transition label; null for a silent (tau) transition. */
  label: string | null;
}

export interface StatCardsProps {
  items: StatItem[];
  /** "start" = label over value, left aligned (metrics); "center" = centered big number. */
  align?: "start" | "center";
  /** Progress visualization for items with a `progress` value. Default "ring". */
  indicator?: StatIndicator;
}

/** Props for a viewer with no interactive surface: it renders `data` and nothing else. Use this
 *  instead of ViewerProps<T> when colorOf/onSelect/actions/format would be ignored. */
export type StaticViewerProps<T> = { data: T };

export interface StatItem {
  label: string;
  value: string | number;
  hint?: string;
  /** Semantic direction; colors the value / indicator (e.g. high fitness = good). */
  tone?: StatTone;
  /** 0..1 fraction. When set, the value renders with the chosen progress indicator. */
  progress?: number;
}

export interface StyledEdge {
  points: [number, number][];
  color?: string;
  /** Linear gradient stroke (first -> last point); 2+ stops override `color` on the path. */
  gradient?: GradientStop[];
  width?: number;
  dash?: string;
  marker_start?: EdgeMarker;
  marker_end?: EdgeMarker;
  /** Marker fill; defaults to the edge color (OC-Declare uses one neutral gray for all markers). */
  marker_color?: string;
  /** Marker base size in px (side of the 12-unit marker viewBox); default scales with `width`. */
  marker_size?: number;
  labels?: EdgeLabel[];
  dots?: EdgeDot[];
  /** Corner radius (px) for rounding the polyline's interior joins; 0 = straight segments. */
  rounded?: number;
}

export interface StyledGraph {
  background?: string;
  padding?: number;
  nodes: StyledNode[];
  edges: StyledEdge[];
  /** Draw edges/markers AFTER nodes so border-centered markers sit on top (OC-Declare). */
  edges_on_top?: boolean;
  legend?: LegendGroup[];
}

/** Host-supplied renderer: draws a `StyledGraph` to a standalone SVG string (usually backed by
 *  the `export_graph_svg` binding). Injected so this package never imports a backend directly. */
export type StyledGraphRenderer = (graph: StyledGraph) => Promise<string>;

export interface StyledIcon {
  kind: IconKind;
  color?: string;
  /** Icon half-size as a fraction of the node's half-extent. */
  scale?: number;
}

export interface StyledLabel {
  text: string;
  size?: number;
  weight?: number;
  color?: string;
  /** Vertical offset from the node center, in px. */
  dy?: number;
  /** Horizontal offset from the node center, in px (e.g. to re-center a text+bullet group). */
  dx?: number;
  /** Word-wrap to fit the node width (max 2 lines, ellipsized). */
  wrap?: boolean;
  /** Kind-indicator glyph left of the text (OCEL type graph: square = event, dot = object).
   *  Ignored on wrapped labels; placement uses an estimated text width. */
  bullet?: MarkingKind;
  /** Bullet fill; defaults to the label color. */
  bullet_color?: string;
}

export interface StyledNode {
  cx: number;
  cy: number;
  w: number;
  h: number;
  shape?: NodeShape;
  fill?: string;
  stroke?: string;
  stroke_width?: number;
  stroke_dash?: string;
  labels?: StyledLabel[];
  marking?: MarkingGroup[];
  /** Vertical offset of the marking row from the node center, in px. */
  marking_dy?: number;
  /** A single decorative glyph (e.g. DFG start/end terminal chrome). */
  icon?: StyledIcon;
}

export interface SupportCtx {
  source: DeclareNode;
  target: DeclareNode;
}

export type SyncProdNetConstructionError =
  | { InvalidPlaceInMarking: PlaceID }
  | "NoFinalMarking"
  | "NoInitialMarking";

export interface TimeConfig {
  /** RFC3339 start applied to the first (non-manual) event of every case. */
  start: string;
  stepSeconds: number;
}

export interface TraceVariants {
  activities: string[];
  act_to_index: Record<string, number>;
  traces: [number[], number][];
}

export type TransitionData = ElementHandlers & {
  label?: string | undefined;
  className?: string;
  style?: React.CSSProperties;
  /** Replace the transition's inner content entirely (e.g. an icon). */
  renderContent?: () => React.ReactNode;
};

export interface TransitionFireStats {
  sync_fires: number;
  model_fires: number;
}

export interface TransitionInfo {
  id: string;
  label: string | null;
}

export type TreeEditorProps = {
  /** The tree to show, in the engine's wire shape (no node ids). */
  tree: ProcessTree;
  readOnly?: boolean;
  /** Turn on editing (operator type, add/wrap/delete, rename, reorder). `readOnly` still wins. */
  editable?: boolean;
  /** Fired on every structural edit with the new tree. */
  onChange?: (tree: ProcessTree) => void;
  /** Replace the layout from `ViewerConfig.layout.processTree`. */
  layoutOverride?: ProcessTreeLayoutFn;
  /** Cosmetics merged over a node's data at render time. */
  nodeOverlay?: (id: string, data: OperatorData | LeafData) => TreeNodePresentation | undefined;
  /** Defaults to `ViewerConfig.layout.renderSvg`. Without either there is no vector export. */
  renderSvg?: StyledGraphRenderer;
  /** Override to avoid a collision when several trees share one export frame. */
  exportKey?: string;
  children?: React.ReactNode;
  className?: string;
};

export type TreeNodePresentation = {
  className?: string;
  style?: React.CSSProperties;
  onClick?: (e: React.MouseEvent) => void;
};

export interface TypeScopeItem {
  id: string;
  label: string;
  kind: "event" | "object";
  count?: number;
}

export interface TypeScopeSelectorProps {
  items: TypeScopeItem[];
  /** Currently-visible ids (the graph's `visibleNodeIds`). */
  value: Set<string>;
  onChange: (next: Set<string>) => void;
  /** Optional host action: reset scope to the host's automatic default. */
  onResetAuto?: () => void;
  /** Whether the current scope equals the automatic default (labels the trigger). */
  isAuto?: boolean;
  /** Shared color resolver so the frequency bars match the graph node colors. */
  colorOf?: ColorResolver;
  triggerVariant?: "soft" | "surface" | "outline";
}

export interface VariantAlignmentResult {
  activities: string[];
  frequency: number;
  result: { Ok: AlignmentResult } | { Err: AlignmentError };
}

/** `<ViewerExportFrame>` renders the only export control in the package. Viewers advertise a vector
 *  rendering through `useRegisterExport` and the nearest frame turns it into an SVG/PNG/JPEG
 *  download, alongside an html-to-image snapshot of its content (`data-export-root` bounds the
 *  snapshot, `data-export-ignore` drops elements from it). Without a frame `useRegisterExport`
 *  no-ops and nothing is exportable. */

/** A viewer's self-contained vector rendering of its current state. */
export interface VectorExportSource {
  /** Build the current view as a standalone SVG string, or null when not ready; reads live state at
   *  call time (not cached), so async renderers see exact on-screen geometry as of the export click. */
  toSvg: () => string | null | Promise<string | null>;
  /** Menu heading for this source's formats. Defaults to a humanized registration key. */
  label?: string;
  /** Optional extra menu content (e.g., a per-viewer row-limit picker), shown under the heading. */
  menuExtras?: ReactNode;
}

export interface ViewerAction {
  id: string;
  label: string;
  icon?: ComponentType<{ size?: number }>;
  /** Limit to a target scope (e.g. only "activity"); undefined = any element. */
  scope?: string;
  run: (target: ViewerTarget) => void;
}

/** Cross-cutting viewer configuration + interactivity, set via `ViewerConfigProvider`; `ViewerProps` may override any field. */
export interface ViewerConfig {
  colorOf?: ColorResolver;
  format?: ViewerFormat;
  alignmentStyle?: AlignmentStyle;
  actions?: ViewerAction[];
  onSelect?: (target: ViewerTarget) => void;
  onElementContextMenu?: (target: ViewerTarget, event: { clientX: number; clientY: number }) => void;
  /** Layout engine for graph viewers; explicit `layoutOverride`/`renderSvg` props still win. */
  layout?: LayoutEngine;
}

export interface ViewerExportFrameProps {
  /** Base name of the downloaded file; the target's extension is appended. */
  filename?: string;
  /** Receive the bytes instead of triggering a browser download (e.g. a native save dialog). */
  onSave?: SaveBytesFn;
  /** Called when an export throws, in addition to the `propel:export-error` window event. */
  onError?: (error: unknown) => void;
  /** The viewer, or any content, to make exportable. The frame is `position: relative` and sizes
   *  nothing on its own; give it a height through `style` and the viewer inside fills it. */
  children: ReactNode;
  style?: CSSProperties;
  /** Show the export control. Off for compact previews; the export context stays active either way. */
  showMenu?: boolean;
  /** Corner the export button sits in. Move it off a viewer's own corner controls. */
  menuPlacement?: ExportMenuPlacement;
}

export interface ViewerFormat {
  number?: (n: number) => string;
  date?: (ms: number) => string;
  duration?: (ms: number) => string;
}

export interface ViewerProps<T> extends ViewerConfig {
  data: T;
  /** Source object handle id, for drill-down. */
  handle?: string;
}

/** A domain element a host can act on. `scope` is the kind ("activity", "objectType", ...). */
export interface ViewerTarget {
  scope: string;
  key: string;
  data?: unknown;
}
